use crate::DigestAlg;
use crate::Error;
use crate::serr;

use vstd::prelude::*;

/// The intermediate value, generated by extract, used by expand
#[derive(Clone, Debug)]
pub struct Prk {
    prk: aws_lc_rs::hkdf::Prk,
}

const fn get_alg(alg: DigestAlg) -> aws_lc_rs::hkdf::Algorithm {
    match alg {
        DigestAlg::Sha256 => aws_lc_rs::hkdf::HKDF_SHA256,
        DigestAlg::Sha384 => aws_lc_rs::hkdf::HKDF_SHA384,
        DigestAlg::Sha512 => aws_lc_rs::hkdf::HKDF_SHA512,
    }
}

verus! {

/// The length, in bytes, of the longest default HKDF salt — the SHA-512
/// output length. Sizes the stack salt buffer in [`hkdf_no_salt`].
///
/// Defined inside `verus!` so the slice-bounds proof in
/// [`no_salt_slice_core`] can relate the chosen salt length to the buffer
/// length; this is the single definition, erased to a plain `const` for the
/// cargo build.
const MAX_SALT_SIZE: usize = 64;

/// The AES-GCM key size for each HKDF output length that HKDF accepts. Verus
/// does not model the crate [`Error`] or `aws-lc-rs`'s `aead::Algorithm`, so
/// the verified code returns this enum and [`get_len`] maps it to the
/// `aws-lc-rs` algorithm.
enum HkdfKeyLen {
    /// A 16-byte key: AES-128-GCM.
    Aes128,
    /// A 24-byte key: AES-192-GCM.
    Aes192,
    /// A 32-byte key: AES-256-GCM.
    Aes256,
}

/// Why [`hkdf_key_len_ok`] rejected an HKDF output length: it was not one of
/// the three AES-GCM key sizes.
enum HkdfKeyLenError {
    /// `len` is not 16, 24, or 32.
    Unsupported,
}

/// The HKDF digest selector, mirroring the crate's [`DigestAlg`] enum as a
/// plain `verus!`-internal type so the salt-length decision and its bound are
/// verified without naming [`DigestAlg`] (which Verus does not model) inside
/// the proof. [`digest_to_hkdf`] converts the crate enum to this one.
#[derive(Clone, Copy)]
enum HkdfDigest {
    /// SHA-256: 32-byte default salt.
    Sha256,
    /// SHA-384: 48-byte default salt.
    Sha384,
    /// SHA-512: 64-byte default salt.
    Sha512,
}

/// Accept an HKDF output length only if it is 16, 24, or 32 bytes, and return
/// the matching AES-GCM key size (VR-009). The esdk side of VR-009
/// (`identity_kdf_key_len_ok`, `check_v2_key_lengths`) checks the same three
/// lengths.
fn hkdf_key_len_ok(len: usize) -> (r: Result<HkdfKeyLen, HkdfKeyLenError>)
    ensures
        (r is Ok) <==> (len == 16 || len == 24 || len == 32),
        (r is Err) <==> (len != 16 && len != 24 && len != 32),
        r matches Ok(HkdfKeyLen::Aes128) <==> len == 16,
        r matches Ok(HkdfKeyLen::Aes192) <==> len == 24,
        r matches Ok(HkdfKeyLen::Aes256) <==> len == 32,
{
    match len {
        16 => Ok(HkdfKeyLen::Aes128),
        24 => Ok(HkdfKeyLen::Aes192),
        32 => Ok(HkdfKeyLen::Aes256),
        _ => Err(HkdfKeyLenError::Unsupported),
    }
}

/// The verified default-salt length for each digest (RFC 5869 §2.2: the
/// no-salt case uses `HashLen` zero bytes). The `ensures` proves the exact
/// value for each digest *and* that it never exceeds [`MAX_SALT_SIZE`], which
/// is what makes the `&salt[..sz]` slice in [`no_salt_slice_core`] in-bounds.
fn salt_size_core(d: HkdfDigest) -> (sz: usize)
    ensures
        sz <= MAX_SALT_SIZE,
        d is Sha256 ==> sz == 32,
        d is Sha384 ==> sz == 48,
        d is Sha512 ==> sz == 64,
{
    match d {
        HkdfDigest::Sha256 => 32,
        HkdfDigest::Sha384 => 48,
        HkdfDigest::Sha512 => MAX_SALT_SIZE,
    }
}

/// Return the first `sz` bytes of the all-zero salt buffer, where `sz` is the
/// digest's default salt length (VR-009). Because `sz <= MAX_SALT_SIZE`, which
/// is the buffer length, the slice cannot panic.
fn no_salt_slice_core(salt: &[u8], d: HkdfDigest) -> (s: &[u8])
    requires
        salt@.len() == MAX_SALT_SIZE,
    ensures
        s@.len() <= MAX_SALT_SIZE,
        d is Sha256 ==> s@.len() == 32,
        d is Sha384 ==> s@.len() == 48,
        d is Sha512 ==> s@.len() == 64,
{
    let sz = salt_size_core(d);
    // Written as `0..sz` because Verus supports `Range` but not `..sz`.
    &salt[0..sz]
}

} // verus!

/// Map the crate's [`DigestAlg`] to the `verus!`-internal [`HkdfDigest`], the
/// thin adapter that keeps [`DigestAlg`] out of the verified salt-length core.
const fn digest_to_hkdf(alg: DigestAlg) -> HkdfDigest {
    match alg {
        DigestAlg::Sha256 => HkdfDigest::Sha256,
        DigestAlg::Sha384 => HkdfDigest::Sha384,
        DigestAlg::Sha512 => HkdfDigest::Sha512,
    }
}

/// Select the `aws-lc-rs` AEAD algorithm for an HKDF output length.
///
/// The length check is the verified [`hkdf_key_len_ok`]. This function maps
/// its result to an `aws-lc-rs` algorithm or an [`Error`].
///
/// # Errors
///
/// Returns an [`Error`] if `len` is not 16, 24, or 32.
fn get_len(len: usize) -> Result<&'static aws_lc_rs::aead::Algorithm, Error> {
    match hkdf_key_len_ok(len) {
        Ok(HkdfKeyLen::Aes128) => Ok(&aws_lc_rs::aead::AES_128_GCM),
        Ok(HkdfKeyLen::Aes192) => Ok(&aws_lc_rs::aead::AES_192_GCM),
        Ok(HkdfKeyLen::Aes256) => Ok(&aws_lc_rs::aead::AES_256_GCM),
        Err(HkdfKeyLenError::Unsupported) => {
            Err(serr(format!("invalid key length {len} for HKDF")))
        }
    }
}

/// Calculate HKDF
///
/// # Errors
///
/// Returns an [`Error`] if `okm.len()` is not 16, 24, or 32, or if the
/// underlying expand operation fails.
pub fn hkdf(
    alg: DigestAlg,
    salt: &[u8],
    ikm: &[u8],
    info: &[&[u8]],
    okm: &mut [u8],
) -> Result<(), Error> {
    let salt = aws_lc_rs::hkdf::Salt::new(get_alg(alg), salt);
    let prk = salt.extract(ikm);
    let inner_okm = prk
        .expand(info, get_len(okm.len())?)
        .map_err(|_| serr("HKDF expand failed".to_owned()))?;
    inner_okm
        .fill(okm)
        .map_err(|_| serr("HKDF expand failed".to_owned()))?;
    Ok(())
}

/// Calculate HKDF, with default salt
///
/// The default salt is a run of zero bytes as long as `alg`'s digest output
/// (32 bytes for SHA-256, 48 for SHA-384, 64 for SHA-512). This is not an
/// arbitrary hard-coded key: RFC 5869 §2.2 specifies that when no salt is
/// provided it is set to a string of `HashLen` zeros, so the all-zero salt
/// below is the standard-mandated value for the no-salt case.
///
/// # Errors
///
/// Returns an [`Error`] if `okm.len()` is not 16, 24, or 32, or if the
/// underlying expand operation fails.
pub fn hkdf_no_salt(
    alg: DigestAlg,
    ikm: &[u8],
    info: &[&[u8]],
    okm: &mut [u8],
) -> Result<(), Error> {
    let salt = [0u8; MAX_SALT_SIZE];
    // The compile-time length of this literal discharges the core's
    // `requires salt@.len() == MAX_SALT_SIZE` by construction here (the adapter
    // boundary, as in T1/T2). Verified core: take the digest's default salt
    // length of leading zero bytes. `no_salt_slice_core` proves
    // `sz <= MAX_SALT_SIZE == salt.len()`, so this slice is in bounds and
    // cannot panic (VR-009, prim half (b)).
    let salt = no_salt_slice_core(&salt, digest_to_hkdf(alg));
    hkdf(alg, salt, ikm, info, okm)
}

/// HKDF Extract
#[must_use]
pub fn hkdf_extract(alg: DigestAlg, salt: &[u8], ikm: &[u8]) -> Prk {
    let salt = aws_lc_rs::hkdf::Salt::new(get_alg(alg), salt);
    let prk = salt.extract(ikm);
    Prk { prk }
}

/// HKDF Expand
///
/// # Errors
///
/// Returns an [`Error`] if `okm.len()` is not 16, 24, or 32, or if the
/// underlying expand operation fails.
pub fn hkdf_expand(prk: &Prk, info: &[&[u8]], okm: &mut [u8]) -> Result<(), Error> {
    let inner_okm = prk
        .prk
        .expand(info, get_len(okm.len())?)
        .map_err(|_| serr("HKDF expand failed".to_owned()))?;
    inner_okm
        .fill(okm)
        .map_err(|_| serr("HKDF expand failed".to_owned()))?;
    Ok(())
}
